<?php
/**
 * Region map for stores that sell in one country: which province, state or
 * region an order comes from, and the per-country data behind the dashboard's
 * region map.
 *
 * Loaded only by the dashboard (Order locations card and its data request),
 * never on the storefront.
 *
 * The map shapes (assets/maps/<cc>.json) and the lookup tables
 * (includes/data/regions/<cc>.php) are generated by tools/regions/ from
 * Natural Earth (public domain), GeoNames postal codes (CC BY 4.0) and
 * WooCommerce's own state lists.
 *
 * @package BrikPanel
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( ! class_exists( 'Brikpanel_Dashboard_Regions' ) ) {

	/**
	 * Region lookup for the dashboard's Order locations card.
	 */
	class Brikpanel_Dashboard_Regions {

		// The day's decision: which country's map the dashboard shows (autoload off).
		const FOCUS_OPTION = 'brikpanel_region_focus';

		// Share of paid orders from one country that opens the map, and the
		// share that keeps it open, so a store near the line does not switch
		// every day.
		const FOCUS_OPEN = 0.90;
		const FOCUS_KEEP = 0.85;

		// Share of that country's orders that must be placed in a region; with
		// less, the map would mostly say "unknown" and the globe stays.
		const FOCUS_PLACED = 0.60;

		// The decision reads the paid orders of the last this many days (the
		// newest FOCUS_SAMPLE of them): a store that turns to one country gets
		// its map within a month, not after a year of mixed history.
		const FOCUS_DAYS = 30;

		// At most this many orders are read for the decision.
		const FOCUS_SAMPLE = 20000;

		// Countries whose region is written with its postal code after a city
		// ("Springfield, IL", "Toronto, ON").
		const CODE_STYLE = array( 'US', 'CA', 'AU', 'BR' );

		/**
		 * The country whose region map the dashboard shows: worked out on the
		 * first data request of the day (or when the order statuses, the order
		 * storage, BrikMarket, the selling countries or the map data change),
		 * then read from the stored decision.
		 *
		 * @param bool $is_hpos    Orders in WooCommerce's own tables.
		 * @param bool $exclude_mp Leave out BrikMarket's marketplace orders, like the card.
		 * @return string Country code, '' when the dashboard keeps the globe.
		 */
		public static function focus_country( $is_hpos, $exclude_mp ) {
			// get_option() keeps the row for the rest of the request.
			$sig    = self::focus_signature( $is_hpos, $exclude_mp );
			$stored = get_option( self::FOCUS_OPTION );
			$today  = wp_date( 'Y-m-d' );
			if ( is_array( $stored ) && $today === ( $stored['day'] ?? '' ) && $sig === ( $stored['sig'] ?? '' ) ) {
				return ! empty( $stored['on'] ) && self::data( (string) $stored['cc'] ) ? (string) $stored['cc'] : '';
			}

			$was = ( is_array( $stored ) && ! empty( $stored['on'] ) ) ? (string) ( $stored['cc'] ?? '' ) : '';
			try {
				$next = self::decide( $is_hpos, $exclude_mp, $was );
			} catch ( Throwable $e ) {
				// A failed query keeps yesterday's map rather than flipping the card.
				$next = array(
					'on' => '' !== $was,
					'cc' => $was,
				);
			}
			$next['day'] = $today;
			$next['sig'] = $sig;
			update_option( self::FOCUS_OPTION, $next, false );

			return $next['on'] ? (string) $next['cc'] : '';
		}

		/**
		 * The stored decision, without working it out: the page prints the
		 * World | Country switch from it so the card header never jumps.
		 *
		 * @return string Country code, '' when there is none.
		 */
		public static function stored_focus_country() {
			$stored = get_option( self::FOCUS_OPTION );
			if ( ! is_array( $stored ) || empty( $stored['on'] ) ) {
				return '';
			}
			$cc = (string) ( $stored['cc'] ?? '' );
			return self::data( $cc ) ? $cc : '';
		}

		/**
		 * Orders, customers and revenue per region of one country for a period.
		 *
		 * Grouped by the state as written first (one row per value, nearly
		 * every order of a store with a state list ends here); only the values
		 * no region was found for are read again by postcode and city.
		 * Customers are counted per address group, so one who ordered with two
		 * different addresses in a region counts twice there (rare).
		 *
		 * @param string $cc         Country code.
		 * @param bool   $is_hpos    Orders in WooCommerce's own tables.
		 * @param bool   $exclude_mp Leave out BrikMarket's marketplace orders.
		 * @param string $start_gmt  From (UTC, Y-m-d H:i:s).
		 * @param string $end_gmt    To (UTC, Y-m-d H:i:s).
		 * @param int    $limit      Read only the newest this many orders (0 = all).
		 * @return array{orders:int,unplaced:int,rows:array<int,array{0:int,1:int,2:float}>}
		 */
		public static function aggregate( $cc, $is_hpos, $exclude_mp, $start_gmt, $end_gmt, $limit = 0 ) {
			global $wpdb;

			$out  = array(
				'orders'   => 0,
				'unplaced' => 0,
				'rows'     => array(),
			);
			$data = self::data( $cc );
			if ( ! $data ) {
				return $out;
			}
			$cc   = strtoupper( (string) $cc );
			$base = self::order_ids_sql( $is_hpos, $exclude_mp, $start_gmt, $end_gmt, $limit );
			$add  = static function ( $idx, $row ) use ( &$out ) {
				$orders         = (int) $row->orders;
				$out['orders'] += $orders;
				if ( $idx < 0 ) {
					$out['unplaced'] += $orders;
					return;
				}
				if ( ! isset( $out['rows'][ $idx ] ) ) {
					$out['rows'][ $idx ] = array( 0, 0, 0.0 );
				}
				$out['rows'][ $idx ][0] += $orders;
				$out['rows'][ $idx ][1] += (int) $row->customers;
				$out['rows'][ $idx ][2] += (float) $row->revenue;
			};

			// 1) By the state as written.
			$q          = self::address_sql( $is_hpos, $base, $cc );
			$state_rows = $wpdb->get_results(
				// Placeholders only; table and column names come from address_sql().
				$wpdb->prepare( "SELECT {$q['state']} AS st, {$q['measures']} FROM {$q['from']} WHERE {$q['where']} GROUP BY st", $q['args'] ) // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
			);
			$open = array();
			foreach ( (array) $state_rows as $row ) {
				$idx = self::resolve( $cc, (string) $row->st );
				if ( $idx < 0 && ! self::is_noshape( $data, (string) $row->st ) ) {
					$open[] = (string) $row->st;
					continue;
				}
				$add( $idx, $row );
			}
			if ( ! $open ) {
				return $out;
			}

			// 2) The rest by postcode (as long as the table needs) and city.
			$pc_len = ! empty( $data['pc'] ) ? (int) $data['pc']['max'] + 3 : 0;
			$in     = count( $open ) <= 500 ? ' AND ' . $q['state'] . ' IN (' . implode( ', ', array_fill( 0, count( $open ), '%s' ) ) . ')' : '';
			$args   = array_merge( $q['args'], $in ? $open : array() );
			$rows   = $wpdb->get_results(
				$wpdb->prepare(
					// Placeholders only; table and column names come from address_sql().
					"SELECT {$q['state']} AS st, LEFT({$q['postcode']}, {$pc_len}) AS pc, {$q['city']} AS city, {$q['measures']} FROM {$q['from']} WHERE {$q['where']}{$in} GROUP BY st, pc, city", // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
					$args
				)
			);
			$open = array_flip( $open );
			$memo = array();
			foreach ( (array) $rows as $row ) {
				if ( ! isset( $open[ (string) $row->st ] ) ) {
					continue;
				}
				$key = $row->st . '|' . $row->pc . '|' . $row->city;
				if ( ! isset( $memo[ $key ] ) ) {
					$memo[ $key ] = self::resolve( $cc, (string) $row->st, (string) $row->pc, (string) $row->city );
				}
				$add( $memo[ $key ], $row );
			}
			return $out;
		}

		/**
		 * Work out the day's decision (focus_country()).
		 *
		 * @param bool   $is_hpos    Orders in WooCommerce's own tables.
		 * @param bool   $exclude_mp Leave out marketplace orders.
		 * @param string $was        Country the map showed until now, '' for the globe.
		 * @return array{on:bool,cc:string,share:float,placed:float,orders:int}
		 */
		private static function decide( $is_hpos, $exclude_mp, $was ) {
			global $wpdb;

			$out   = array(
				'on'     => false,
				'cc'     => '',
				'share'  => 0.0,
				'placed' => 0.0,
				'orders' => 0,
			);
			$end   = gmdate( 'Y-m-d H:i:s' );
			$start = gmdate( 'Y-m-d H:i:s', time() - self::FOCUS_DAYS * DAY_IN_SECONDS );
			$base  = self::order_ids_sql( $is_hpos, $exclude_mp, $start, $end, self::FOCUS_SAMPLE );

			if ( $is_hpos ) {
				$sql = "SELECT COALESCE(ba.country, '') AS cc, COUNT(*) AS n FROM ({$base['sql']}) t"
					. " LEFT JOIN {$wpdb->prefix}wc_order_addresses ba ON ba.order_id = t.id AND ba.address_type = 'billing'"
					. ' GROUP BY cc';
			} else {
				$sql = "SELECT COALESCE(pmc.meta_value, '') AS cc, COUNT(*) AS n FROM ({$base['sql']}) t"
					. brikpanel_sql_single_meta_join( 'post', 'pmc', 't.id', '_billing_country' )
					. ' GROUP BY cc';
			}
			// Placeholders only; table and column names are fixed above.
			$counts = array();
			foreach ( (array) $wpdb->get_results( $wpdb->prepare( $sql, $base['args'] ) ) as $row ) { // phpcs:ignore WordPress.DB.PreparedSQL.NotPrepared
				$counts[ strtoupper( (string) $row->cc ) ] = (int) $row->n;
			}
			$total = array_sum( $counts );

			$allowed = ( function_exists( 'WC' ) && WC()->countries ) ? array_keys( (array) WC()->countries->get_allowed_countries() ) : array();
			$pick    = self::pick( $counts, $allowed, $was );
			$out     = array_merge( $out, $pick );
			$out['orders'] = $total;
			if ( ! $pick['on'] ) {
				return $out;
			}

			// Enough of those orders must be placed in a region.
			$agg           = self::aggregate( $pick['cc'], $is_hpos, $exclude_mp, $start, $end, self::FOCUS_SAMPLE );
			$out['placed'] = $agg['orders'] ? round( ( $agg['orders'] - $agg['unplaced'] ) / $agg['orders'], 4 ) : 1.0;
			$out['on']     = self::placed_enough( $agg['orders'], $agg['unplaced'] );
			return $out;
		}

		/**
		 * The country whose map a store gets from its orders per country: the
		 * one with 90% of them (85% to keep a map it already shows), or the
		 * only country WooCommerce sells to. It must have a map. A month
		 * without a paid order keeps the map the store had.
		 *
		 * @param array<string,int> $counts  Orders per billing country ('' = none).
		 * @param string[]          $allowed Countries WooCommerce sells to.
		 * @param string            $was     Country the map showed until now, '' for the globe.
		 * @return array{on:bool,cc:string,share:float}
		 */
		public static function pick( array $counts, array $allowed, $was ) {
			$total = array_sum( $counts );
			arsort( $counts );
			if ( 1 === count( $allowed ) ) {
				$cc    = strtoupper( (string) reset( $allowed ) );
				$share = 1.0;
			} elseif ( 0 === $total ) {
				return array(
					'on'    => '' !== (string) $was && null !== self::data( $was ),
					'cc'    => strtoupper( (string) $was ),
					'share' => 0.0,
				);
			} else {
				$cc    = $counts ? strtoupper( (string) array_key_first( $counts ) ) : '';
				$share = $total ? $counts[ array_key_first( $counts ) ] / $total : 0.0;
			}
			$need = ( '' !== $cc && $was === $cc ) ? self::FOCUS_KEEP : self::FOCUS_OPEN;
			return array(
				'on'    => '' !== $cc && null !== self::data( $cc ) && $share >= $need,
				'cc'    => $cc,
				'share' => round( $share, 4 ),
			);
		}

		/**
		 * Whether enough of a country's orders are placed in a region for its
		 * map to say something (a store with a handful of orders always gets it).
		 *
		 * @param int $orders   The country's orders.
		 * @param int $unplaced Those no region was found for.
		 * @return bool
		 */
		public static function placed_enough( $orders, $unplaced ) {
			return $orders < 10 || ( $orders - $unplaced ) / $orders >= self::FOCUS_PLACED;
		}

		/**
		 * SQL selecting the ids of the paid orders the Order locations card
		 * counts in a period (same statuses and exclusions as the card).
		 *
		 * @param bool   $is_hpos    Orders in WooCommerce's own tables.
		 * @param bool   $exclude_mp Leave out marketplace orders.
		 * @param string $start_gmt  From (UTC).
		 * @param string $end_gmt    To (UTC).
		 * @param int    $limit      Newest this many (0 = all).
		 * @return array{sql:string,args:array}
		 */
		public static function order_ids_sql( $is_hpos, $exclude_mp, $start_gmt, $end_gmt, $limit = 0 ) {
			global $wpdb;

			$statuses = brikpanel_paid_order_statuses();
			$marks    = implode( ', ', array_fill( 0, count( $statuses ), '%s' ) );
			$admin    = brikpanel_admin_order_exclusion_sql( $is_hpos, $is_hpos ? 'o.id' : 'p.ID' );
			$mp       = $exclude_mp ? brikpanel_marketplace_order_exclusion_sql( $is_hpos, $is_hpos ? 'o.id' : 'p.ID' ) : array(
				'sql'  => '',
				'args' => array(),
			);
			$limit    = (int) $limit;

			if ( $is_hpos ) {
				$sql = "SELECT o.id FROM {$wpdb->prefix}wc_orders o WHERE o.type = 'shop_order' AND o.status IN ({$marks})"
					. str_replace( 'customer_id', 'o.customer_id', $admin['sql'] ) . $mp['sql']
					. ' AND o.date_created_gmt >= %s AND o.date_created_gmt <= %s'
					. ( $limit > 0 ? ' ORDER BY o.date_created_gmt DESC LIMIT ' . $limit : '' );
			} else {
				$sql = "SELECT p.ID AS id FROM {$wpdb->posts} p WHERE p.post_type = 'shop_order' AND p.post_status IN ({$marks})"
					. $admin['sql'] . $mp['sql']
					. ' AND p.post_date_gmt >= %s AND p.post_date_gmt <= %s'
					. ( $limit > 0 ? ' ORDER BY p.post_date_gmt DESC LIMIT ' . $limit : '' );
			}
			return array(
				'sql'  => $sql,
				'args' => array_merge( $statuses, $admin['args'], (array) $mp['args'], array( $start_gmt, $end_gmt ) ),
			);
		}

		/**
		 * FROM and WHERE clauses and expressions reading the billing address of
		 * the orders in $base that are in one country, with the card's measures.
		 *
		 * @param bool   $is_hpos Orders in WooCommerce's own tables.
		 * @param array  $base    order_ids_sql() result.
		 * @param string $cc      Country code.
		 * @return array{from:string,where:string,state:string,postcode:string,city:string,measures:string,args:array}
		 */
		private static function address_sql( $is_hpos, array $base, $cc ) {
			global $wpdb;

			if ( $is_hpos ) {
				$fx = brikpanel_base_total_sql( true, 'o.id', 'o.total_amount', 'bpfxrg' );
				return array(
					'from'     => "({$base['sql']}) t JOIN {$wpdb->prefix}wc_orders o ON o.id = t.id"
						. " JOIN {$wpdb->prefix}wc_order_addresses ba ON ba.order_id = o.id AND ba.address_type = 'billing'"
						. $fx['join'],
					'where'    => 'ba.country = %s',
					'state'    => "COALESCE(ba.state, '')",
					'postcode' => "COALESCE(ba.postcode, '')",
					'city'     => "COALESCE(ba.city, '')",
					'measures' => 'COUNT(*) AS orders, COUNT(DISTINCT IF(o.customer_id > 0, CONCAT(\'u-\', o.customer_id),'
						. " IF(ba.email IS NOT NULL AND ba.email <> '', CONCAT('e-', LOWER(ba.email)), CONCAT('o-', o.id)))) AS customers,"
						. " COALESCE(SUM({$fx['expr']}), 0) AS revenue",
					'args'     => array_merge( $base['args'], array( $cc ) ),
				);
			}

			$o = self::legacy_order_fields_sql( $base, self::legacy_fields() );
			return array(
				'from'     => "({$o['sql']}) o",
				'where'    => 'o.cc = %s',
				'state'    => "COALESCE(o.st, '')",
				'postcode' => "COALESCE(o.pc, '')",
				'city'     => "COALESCE(o.city, '')",
				'measures' => 'COUNT(*) AS orders, ' . self::legacy_customers_sql() . ' AS customers, ' . self::legacy_revenue_sql() . ' AS revenue',
				'args'     => array_merge( $o['args'], array( $cc ) ),
			);
		}

		/**
		 * The old order storage (posts and their meta): one row per order of
		 * $base with the meta values asked for, read in one pass over the meta
		 * table. Joining the meta table once per value, each join pinned to its
		 * first row, took ten times as long on a store with a few thousand
		 * orders. A value stored twice (broken data) gives one of its copies,
		 * never a second row.
		 *
		 * @param array                $base   order_ids_sql() result.
		 * @param array<string,string> $fields Column alias => meta key (internal keys only).
		 * @return array{sql:string,args:array}
		 */
		public static function legacy_order_fields_sql( array $base, array $fields ) {
			global $wpdb;

			$cols = array();
			foreach ( $fields as $alias => $key ) {
				$cols[] = "MAX(CASE WHEN pm.meta_key = '" . esc_sql( $key ) . "' THEN pm.meta_value END) AS " . preg_replace( '/[^a-z_]/', '', (string) $alias );
			}
			$keys = "'" . implode( "', '", array_map( 'esc_sql', array_values( $fields ) ) ) . "'";
			return array(
				'sql'  => 'SELECT t.id, ' . implode( ', ', $cols ) . " FROM ({$base['sql']}) t JOIN {$wpdb->postmeta} pm ON pm.post_id = t.id AND pm.meta_key IN ({$keys}) GROUP BY t.id",
				'args' => $base['args'],
			);
		}

		/**
		 * The order meta the Order locations card reads from the old storage,
		 * as legacy_order_fields_sql() columns.
		 *
		 * @return array<string,string>
		 */
		public static function legacy_fields() {
			return array(
				'cc'    => '_billing_country',
				'st'    => '_billing_state',
				'pc'    => '_billing_postcode',
				'city'  => '_billing_city',
				'cu'    => '_customer_user',
				'em'    => '_billing_email',
				'total' => '_order_total',
				'base'  => defined( 'BRIKPANEL_BASE_TOTAL_META' ) ? BRIKPANEL_BASE_TOTAL_META : '_brikpanel_base_total',
			);
		}

		/**
		 * Customers over legacy_fields() rows (o): a registered customer once,
		 * a guest once per email, an anonymous guest once per order.
		 *
		 * @return string
		 */
		public static function legacy_customers_sql() {
			return "COUNT(DISTINCT IF(CAST(COALESCE(o.cu, '0') AS UNSIGNED) > 0, CONCAT('u-', o.cu),"
				. " IF(o.em IS NOT NULL AND o.em <> '', CONCAT('e-', LOWER(o.em)), CONCAT('o-', o.id))))";
		}

		/**
		 * Sales over legacy_fields() rows (o), in the store's currency (the
		 * converted snapshot when an order has one, as brikpanel_base_total_sql()).
		 *
		 * @return string
		 */
		public static function legacy_revenue_sql() {
			return "COALESCE(SUM(COALESCE(NULLIF(o.base, ''), CAST(o.total AS DECIMAL(20,4)))), 0)";
		}

		/**
		 * What makes yesterday's decision stale besides the day.
		 *
		 * @param bool $is_hpos    Orders in WooCommerce's own tables.
		 * @param bool $exclude_mp Marketplace orders left out.
		 * @return string
		 */
		private static function focus_signature( $is_hpos, $exclude_mp ) {
			$statuses = brikpanel_paid_order_statuses();
			sort( $statuses );
			return md5(
				implode( ',', $statuses ) . '|' . ( $is_hpos ? 1 : 0 ) . '|' . ( $exclude_mp ? 1 : 0 )
				. '|' . get_option( 'woocommerce_allowed_countries', 'all' )
				. '|' . implode( ',', (array) get_option( 'woocommerce_specific_allowed_countries', array() ) )
				. '|' . implode( ',', (array) get_option( 'woocommerce_all_except_countries', array() ) )
				. '|' . self::version() . '|' . self::FOCUS_DAYS
			);
		}

		/**
		 * Whether a state value is one of the codes that are not a place (US Armed Forces).
		 *
		 * @param array  $data  Country data.
		 * @param string $state State as stored.
		 * @return bool
		 */
		private static function is_noshape( $data, $state ) {
			return '' !== $state && isset( $data['noshape'][ strtoupper( $state ) ] );
		}

		/**
		 * The region an address is shown with in the Top cities list: its key
		 * (to merge spellings of one city) and its name, the postal code where
		 * that is how people write it ("Springfield, IL").
		 *
		 * Countries without a region map show WooCommerce's state name, or the
		 * state as the customer wrote it.
		 *
		 * @param string $cc       Country code.
		 * @param string $state    Billing state.
		 * @param string $postcode Billing postcode.
		 * @param string $city     Billing city.
		 * @return array{0:string,1:string} Key and name, '' when unknown.
		 */
		public static function city_region( $cc, $state, $postcode, $city ) {
			$cc    = strtoupper( (string) $cc );
			$state = trim( (string) $state );
			if ( self::data( $cc ) ) {
				$idx = self::resolve( $cc, $state, $postcode, $city );
				if ( $idx < 0 ) {
					return array( '', '' );
				}
				$key = self::key( $cc, $idx );
				return array( $key, in_array( $cc, self::CODE_STYLE, true ) && preg_match( '/^[A-Z]{2,3}$/', $key ) ? $key : self::name( $cc, $idx ) );
			}
			if ( '' === $state ) {
				return array( '', '' );
			}
			$states = self::woo_states( $cc );
			$code   = strtoupper( $state );
			if ( isset( $states[ $code ] ) ) {
				return array( $code, $states[ $code ] );
			}
			$plain = trim( wp_strip_all_tags( $state ) );
			return array( 's:' . self::fold( $plain ), brikpanel_substr( $plain, 0, 40 ) );
		}

		/**
		 * Countries with a region map and the word their lists use.
		 *
		 * @return array<string,string> 'TR' => 'province', 'US' => 'state', 'GB' => 'region'...
		 */
		public static function countries() {
			$index = self::index();
			return $index['cc'];
		}

		/**
		 * Version of the map and lookup data: part of the dashboard's cache key
		 * and of the map file's address.
		 *
		 * @return string
		 */
		public static function version() {
			$index = self::index();
			return $index['v'];
		}

		/**
		 * One country's lookup data (includes/data/regions/<cc>.php).
		 *
		 * @param string $cc Country code.
		 * @return array|null Null when the country has no region map.
		 */
		public static function data( $cc ) {
			static $cache = array();

			$cc = strtoupper( (string) $cc );
			if ( array_key_exists( $cc, $cache ) ) {
				return $cache[ $cc ];
			}
			$cache[ $cc ] = null;

			$countries = self::countries();
			if ( ! preg_match( '/^[A-Z]{2}$/', $cc ) || ! isset( $countries[ $cc ] ) ) {
				return null;
			}
			$file = self::dir() . strtolower( $cc ) . '.php';
			$data = is_readable( $file ) ? include $file : null;
			if ( is_array( $data ) && ! empty( $data['keys'] ) && isset( $data['woo'], $data['alias'] ) ) {
				$cache[ $cc ] = $data;
			}
			return $cache[ $cc ];
		}

		/**
		 * The region an address is in, as an index into data( $cc )['keys'].
		 *
		 * Tried in order: the state code (WooCommerce's, current or older, and
		 * "TR-34" style), the state as written, the postcode, the city as
		 * written. Works for orders from any source (checkout, REST, imports,
		 * marketplaces), which is why nothing here is country specific.
		 *
		 * @param string $cc       Country code.
		 * @param string $state    Billing state as stored.
		 * @param string $postcode Billing postcode.
		 * @param string $city     Billing city.
		 * @return int Region index, -1 when it cannot be told.
		 */
		public static function resolve( $cc, $state, $postcode = '', $city = '' ) {
			$data = self::data( $cc );
			if ( ! $data ) {
				return -1;
			}
			$cc    = strtoupper( (string) $cc );
			$state = trim( (string) $state );

			if ( '' !== $state ) {
				$code  = strtoupper( $state );
				$codes = array( $code, $cc . $code );
				$bare  = '';
				if ( 0 === strpos( $code, $cc . '-' ) ) {
					$bare    = substr( $state, strlen( $cc ) + 1 );
					$codes[] = strtoupper( $bare );
					$codes[] = $cc . strtoupper( $bare );
				}
				foreach ( $codes as $try ) {
					if ( isset( $data['woo'][ $try ] ) ) {
						return (int) $data['woo'][ $try ];
					}
					if ( isset( $data['noshape'][ $try ] ) ) {
						return -1;
					}
				}
				$hit = self::by_name( $data, $state );
				if ( $hit < 0 && '' !== $bare ) {
					$hit = self::by_name( $data, $bare );
				}
				if ( $hit >= 0 ) {
					return $hit;
				}
			}

			if ( ! empty( $data['pc'] ) && '' !== (string) $postcode ) {
				$code = self::fold_postcode( $postcode, $data['pc']['mode'] );
				$max  = min( strlen( $code ), (int) $data['pc']['max'] );
				for ( $i = 1; $i <= $max; $i++ ) {
					$prefix = substr( $code, 0, $i );
					if ( isset( $data['pc']['t'][ $prefix ] ) ) {
						return (int) $data['pc']['t'][ $prefix ];
					}
				}
			}

			// "Praha 4", "Lyon 3e", "Wien 1010": the city without its district number.
			$hit = self::by_name( $data, $city );
			if ( $hit < 0 ) {
				$bare = (string) preg_replace( '/(\s+\S*\d\S*)+$/u', '', trim( (string) $city ) );
				if ( '' !== $bare && $bare !== trim( (string) $city ) ) {
					$hit = self::by_name( $data, $bare );
				}
			}
			return $hit;
		}

		/**
		 * A region's code (the map file's key).
		 *
		 * @param string $cc  Country code.
		 * @param int    $idx Region index.
		 * @return string '' when unknown.
		 */
		public static function key( $cc, $idx ) {
			$data = self::data( $cc );
			return ( $data && isset( $data['keys'][ $idx ] ) ) ? (string) $data['keys'][ $idx ] : '';
		}

		/**
		 * A region's name in the admin's language: WooCommerce's own (translated)
		 * state name when the region is one of its states, ours otherwise.
		 *
		 * @param string $cc  Country code.
		 * @param int    $idx Region index.
		 * @return string Plain text, '' when unknown.
		 */
		public static function name( $cc, $idx ) {
			$data = self::data( $cc );
			if ( ! $data || ! isset( $data['keys'][ $idx ] ) ) {
				return '';
			}
			$key    = (string) $data['keys'][ $idx ];
			$states = self::woo_states( $cc );
			if ( isset( $states[ $key ] ) && '' !== $states[ $key ] ) {
				return $states[ $key ];
			}
			if ( isset( $data['names'][ $idx ] ) ) {
				$names = $data['names'][ $idx ];
				$lang  = strtolower( substr( (string) get_user_locale(), 0, 2 ) );
				return isset( $names[ $lang ] ) ? (string) $names[ $lang ] : (string) $names['en'];
			}
			return $key;
		}

		/**
		 * Postcode as the lookup tables store it: digits only, the British
		 * outward code ("SW1A 1AA" → "SW1A"), Argentina's province letter
		 * ("C1000AAA" → "C"), or letters and digits.
		 *
		 * @param string $code Postcode as typed.
		 * @param string $mode 'digits', 'gb', 'ar' or 'alnum'.
		 * @return string
		 */
		public static function fold_postcode( $code, $mode ) {
			// Full-width digits (Japanese keyboards) count as digits.
			$code = strtr( (string) $code, array_combine( self::fullwidth_digits(), range( '0', '9' ) ) );
			$code = preg_replace( '/[^A-Z0-9]/', '', strtoupper( $code ) );
			if ( 'digits' === $mode ) {
				return (string) preg_replace( '/\D/', '', $code );
			}
			if ( 'gb' === $mode && strlen( $code ) >= 5 && preg_match( '/\d[A-Z]{2}$/', $code ) ) {
				return substr( $code, 0, -3 );
			}
			if ( 'ar' === $mode ) {
				return preg_match( '/^[A-Z]\d{4}/', $code ) ? $code[0] : (string) preg_replace( '/\D/', '', $code );
			}
			return (string) $code;
		}

		/**
		 * The region a name points to (state or city as written).
		 *
		 * @param array  $data Country data.
		 * @param string $text Name.
		 * @return int Region index, -1 when no region (or more than one) has this name.
		 */
		private static function by_name( $data, $text ) {
			$words = self::words( $text );
			if ( '' === $words ) {
				return -1;
			}
			$folded = str_replace( ' ', '', $words );
			if ( isset( $data['alias'][ $folded ] ) ) {
				return (int) $data['alias'][ $folded ];
			}
			$loose = implode( '', array_diff( explode( ' ', $words ), self::generic_words() ) );
			if ( '' !== $loose && isset( $data['alias'][ $loose ] ) ) {
				return (int) $data['alias'][ $loose ];
			}
			return -1;
		}

		/**
		 * WooCommerce's state names for a country, decoded to plain text.
		 *
		 * @param string $cc Country code.
		 * @return array<string,string>
		 */
		private static function woo_states( $cc ) {
			static $cache = array();
			if ( ! isset( $cache[ $cc ] ) ) {
				$cache[ $cc ] = array();
				if ( function_exists( 'WC' ) && WC()->countries ) {
					foreach ( (array) WC()->countries->get_states( $cc ) as $code => $name ) {
						$cache[ $cc ][ (string) $code ] = html_entity_decode( wp_strip_all_tags( (string) $name ), ENT_QUOTES, 'UTF-8' );
					}
				}
			}
			return $cache[ $cc ];
		}

		/**
		 * The supported countries and data version (includes/data/regions/index.php).
		 *
		 * @return array{v:string,cc:array<string,string>}
		 */
		private static function index() {
			static $index = null;
			if ( null === $index ) {
				$file  = self::dir() . 'index.php';
				$data  = is_readable( $file ) ? include $file : null;
				$index = ( is_array( $data ) && isset( $data['v'], $data['cc'] ) && is_array( $data['cc'] ) )
					? $data
					: array(
						'v'  => '',
						'cc' => array(),
					);
			}
			return $index;
		}

		/**
		 * Folder of the generated lookup files.
		 *
		 * @return string
		 */
		private static function dir() {
			return ( defined( 'BRIKPANEL_PATH' ) ? BRIKPANEL_PATH : dirname( __DIR__, 2 ) . '/' ) . 'includes/data/regions/';
		}

		/**
		 * Full-width digits ０-９.
		 *
		 * @return string[]
		 */
		private static function fullwidth_digits() {
			static $digits = null;
			if ( null === $digits ) {
				$digits = array();
				for ( $cp = 0xFF10; $cp <= 0xFF19; $cp++ ) {
					$digits[] = html_entity_decode( '&#' . $cp . ';', ENT_QUOTES, 'UTF-8' );
				}
			}
			return $digits;
		}

		/**
		 * Fold a place name to a matching key: no accents, no case, letters and
		 * digits only. "İSTANBUL", "Istanbul" and "istanbul" give the same key.
		 *
		 * The same function builds the alias keys in tools/regions/, so it must
		 * give the same result on every host: it never depends on mbstring or on
		 * the site language (remove_accents() turns "ü" into "ue" on a German
		 * site, so it always gets one fixed locale here).
		 *
		 * @param string $text Name as typed or listed.
		 * @return string Folded key, '' when nothing is left.
		 */
		public static function fold( $text ) {
			return str_replace( ' ', '', self::words( $text ) );
		}

		/**
		 * fold() without the words that only say what kind of place it is:
		 * "Istanbul Province", "İstanbul ili", "Московская обл.", "Région
		 * Bretagne" give the same key as the bare name.
		 *
		 * @param string $text Name as typed or listed.
		 * @return string Folded key, '' when nothing is left.
		 */
		public static function loose( $text ) {
			$words = array_diff( explode( ' ', self::words( $text ) ), self::generic_words() );
			return implode( '', $words );
		}

		/**
		 * The name lowercased, without accents, its words separated by one space.
		 *
		 * @param string $text Name as typed or listed.
		 * @return string
		 */
		private static function words( $text ) {
			$text = trim( (string) $text );
			if ( '' === $text ) {
				return '';
			}

			$text = remove_accents( $text, 'en_US' );
			$text = strtr( $text, self::lower_map() );
			$text = strtolower( $text );

			$clean = @preg_replace( '/[^\p{L}\p{N}]+/u', ' ', $text ); // phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged -- invalid UTF-8 returns null, handled below.
			if ( null === $clean ) {
				$clean = preg_replace( '/[\s\-_.,;:\'"()\/]+/', ' ', $text );
			}

			return trim( (string) $clean );
		}

		/**
		 * Words that say "province", "region", "city of" and so on in the
		 * languages of the supported countries, as words() writes them.
		 *
		 * @return string[]
		 */
		private static function generic_words() {
			static $list = null;
			if ( null === $list ) {
				$list = array(
					// English, Spanish, Portuguese, Italian, French.
					'province', 'state', 'region', 'county', 'district', 'department', 'prefecture', 'governorate', 'territory',
					'municipality', 'city', 'of', 'the', 'and', 'provincia', 'departamento', 'departement', 'regiao', 'regione',
					'estado', 'distrito', 'comunidad', 'comunidade', 'autonoma', 'autonomous', 'de', 'del', 'la', 'las', 'los',
					'el', 'do', 'da', 'dos', 'das', 'di', 'della', 'du', 'des', 'le', 'les',
					// Russian and other names in Latin letters.
					'oblast', 'krai', 'kray', 'okrug', 'respublika', 'republic', 'voivodeship', 'emirate', 'emirat',
					// German, Dutch, Polish, Czech and Slovak, Hungarian, Romanian, Swedish, Norwegian, Finnish,
					// Estonian, Lithuanian, Turkish.
					'land', 'bundesland', 'kreis', 'provincie', 'wojewodztwo', 'woj', 'kraj', 'megye', 'varmegye', 'judetul',
					'judet', 'municipiul', 'lan', 'fylke', 'maakunta', 'maakond', 'apskritis', 'il', 'ili',
					// Indonesian and Malay.
					'provinsi', 'daerah', 'khusus', 'istimewa', 'dki', 'negeri', 'wilayah', 'persekutuan',
					// Russian, Ukrainian, Bulgarian, Greek, Persian, Arabic.
					'область', 'обл', 'край', 'республика', 'респ', 'город', 'г', 'автономный', 'автономная', 'округ', 'ао',
					'місто', 'м', 'автономна', 'республіка', 'област', 'περιφερεια', 'استان', 'امارة', 'إمارة', 'محافظة', 'ولاية',
				);
			}
			return $list;
		}

		/**
		 * Uppercase => lowercase for the scripts remove_accents() leaves alone
		 * (Cyrillic, Greek), with Greek accents and final sigma folded too.
		 *
		 * @return array<string,string>
		 */
		private static function lower_map() {
			static $map = null;
			if ( null !== $map ) {
				return $map;
			}

			$map = array();
			$chr = static function ( $cp ) {
				return html_entity_decode( '&#' . (int) $cp . ';', ENT_QUOTES, 'UTF-8' );
			};

			// Cyrillic: А-Я lowercase 0x20 above, Ѐ-Џ 0x50 above; ё folds to е.
			for ( $cp = 0x410; $cp <= 0x42F; $cp++ ) {
				$map[ $chr( $cp ) ] = $chr( $cp + 0x20 );
			}
			for ( $cp = 0x400; $cp <= 0x40F; $cp++ ) {
				$map[ $chr( $cp ) ] = $chr( $cp + 0x50 );
			}
			$map[ $chr( 0x451 ) ] = $chr( 0x435 );
			$map[ $chr( 0x401 ) ] = $chr( 0x435 );

			// Greek: Α-Ω lowercase 0x20 above (U+03A2 is unassigned).
			for ( $cp = 0x391; $cp <= 0x3A9; $cp++ ) {
				if ( 0x3A2 !== $cp ) {
					$map[ $chr( $cp ) ] = $chr( $cp + 0x20 );
				}
			}
			$greek = array(
				0x386 => 0x3B1, 0x388 => 0x3B5, 0x389 => 0x3B7, 0x38A => 0x3B9, 0x38C => 0x3BF, 0x38E => 0x3C5, 0x38F => 0x3C9,
				0x3AC => 0x3B1, 0x3AD => 0x3B5, 0x3AE => 0x3B7, 0x3AF => 0x3B9, 0x3CC => 0x3BF, 0x3CD => 0x3C5, 0x3CE => 0x3C9,
				0x3AA => 0x3B9, 0x3AB => 0x3C5, 0x3CA => 0x3B9, 0x3CB => 0x3C5, 0x390 => 0x3B9, 0x3B0 => 0x3C5, 0x3C2 => 0x3C3,
			);
			foreach ( $greek as $from => $to ) {
				$map[ $chr( $from ) ] = $chr( $to );
			}

			return $map;
		}
	}
}
